    edges = [grid[sr][sc+1], grid[sr+2][sc+1], grid[sr+1][sc], grid[sr+1][sc+2]]
    center = grid[sr+1][sc+1]
    return corners, edges, center, Counter(corners+edges+[center])

def get_adjacent_edges_corner(corners, edges, corner_idx):
    """Get 2 edges adjacent to corner at given index"""
    if corner_idx == 0:  # top-left
        return edges[0], edges[2]  # top, left
    elif corner_idx == 1:  # top-right
        return edges[0], edges[3]  # top, right
    elif corner_idx == 2:  # bottom-left
        return edges[1], edges[2]  # bottom, left
    else:  # corner_idx == 3 (bottom-right)
        return edges[1], edges[3]  # bottom, right

def transform(grid):
    H, W = len(grid), len(grid[0])
    out_H, out_W = H//3, W//3
    result = [[0]*out_W for _ in range(out_H)]

    for br in range(out_H):
        for bc in range(out_W):
            corners, edges, center, all_c = get_block_features(grid, br, bc)
            corner_counts = Counter(corners)

