                if diff_corner_count is not None:
                    # Find the diff corner's index and its adjacent edges
                    diff_idx = corners.index(diff_corner_count)
                    e1, e2 = get_adjacent_edges_corner(corners, edges, diff_idx)

                    if e1 == e2:
                        # Both edges same
                        if e1 == diff_corner_count:
                            result[br][bc] = diff_corner_count
                        elif e1 == center:
                            result[br][bc] = diff_corner_count
                        else:
